<div class="d-flex flex-wrap justify-content-between align-items-end mb-4 gap-2"><div><h1 class="page-title">Liquidar comisiones</h1><p class="page-sub">Comisión sobre servicios cobrados por empleado en el periodo</p></div>
<form class="d-flex gap-2 align-items-end" method="get"><div><label class="form-label small mb-0">Desde</label><input type="date" name="desde" value="<?= e($d) ?>" class="form-control form-control-sm"></div>
<div><label class="form-label small mb-0">Hasta</label><input type="date" name="hasta" value="<?= e($h) ?>" class="form-control form-control-sm"></div><button class="btn btn-sm btn-primary">Calcular</button></form></div>
<div class="cw-card mb-3"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Empleado</th><th>Cargo</th><th class="text-end">Órdenes</th><th class="text-end">Ventas servicios</th><th class="text-end">Comisión</th><th>Estado</th><th></th></tr></thead><tbody>
<?php foreach ($emps as $e): ?><tr><td><b><?= e($e['nombre']) ?></b></td><td><?= e($e['cargo']) ?></td><td class="text-end"><?= $e['ordenes'] ?></td><td class="text-end"><?= money($e['ventas']) ?></td><td class="text-end fw-bold text-success"><?= money($e['comision']) ?></td>
<td><?= $e['pagado'] > 0 ? '<span class="badge badge-soft-success">Pagada ' . money($e['pagado']) . '</span>' : '<span class="badge badge-soft-warning">Por pagar</span>' ?></td>
<td class="text-end"><?php if ($e['pagado'] <= 0 && $e['comision'] > 0): ?><form method="post" action="<?= url('comisiones/pagar') ?>" class="d-inline"><?= csrf_field() ?><input type="hidden" name="empleado_id" value="<?= $e['id'] ?>"><input type="hidden" name="desde" value="<?= e($d) ?>"><input type="hidden" name="hasta" value="<?= e($h) ?>"><button class="btn btn-sm btn-grad" data-confirm="¿Registrar el pago y cargarlo a gastos?"><i class="bi bi-cash-coin"></i> Pagar</button></form><?php endif; ?></td></tr>
<?php endforeach; if (!$emps): ?><tr><td colspan="7" class="text-center text-muted py-5">No hay empleados activos</td></tr><?php endif; ?></tbody></table></div></div>
<div class="cw-card"><div class="card-h"><h6>Pagos realizados</h6></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Fecha</th><th>Empleado</th><th>Periodo</th><th class="text-end">Ventas</th><th class="text-end">Pagado</th></tr></thead><tbody>
<?php foreach ($hist as $x): ?><tr><td><?= fdate($x['created_at'], true) ?></td><td><b><?= e($x['empleado']) ?></b></td><td><?= fdate($x['desde']) ?> – <?= fdate($x['hasta']) ?></td><td class="text-end"><?= money($x['ventas']) ?></td><td class="text-end fw-bold"><?= money($x['monto']) ?></td></tr><?php endforeach; if (!$hist): ?><tr><td colspan="5" class="text-center text-muted py-4">Sin pagos</td></tr><?php endif; ?></tbody></table></div></div>
